#!/usr/bin/env python3
"""Bootstrap Capability 011 - Portable Editorial Project resume and export.

Preview is non-mutating. Apply restores every generator-owned Capability 011
artifact from compressed deterministic snapshots, supports partial recovery,
and runs the complete repository validation suite.
"""

from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
import subprocess
import sys
from pathlib import Path


EXPECTED_REPOSITORY = "Ramrattan-AI-Editorial-Studio"
EXPECTED_BRANCHES = {
    "feature/capability-011-portable-editorial-project-resume-export",
    "docs/capability-011-delivery-status-reconciliation",
}
SCRIPT_PATH = "scripts/bootstrap_capability011_portable_editorial_project.py"
SENTINEL = "CAPABILITY_011_PORTABLE_EDITORIAL_PROJECT_COMPLETE"

_BLOBS = {
    "CHANGELOG.md": "",
    "ROADMAP.md": "",
    "docs/VERSION_ONE_SCORECARD.md": "",
    "docs/architecture/Portable_Editorial_Project.md": "",
    "docs/architecture/adr/README.md": "",
    "docs/product/Current_Product_Focus.md": "",
    "docs/product/PRD_v1.3.md": "",
    "docs/product/Release_v1.0.md": "",
    "studio/publication_package.py": "",
    "studio/portable_editorial_project.py": "",
    "tests/test_capability010_documentation.py": "",
    "tests/test_rc1_checkpoint.py": "",
    "tests/test_capability011_portable_editorial_project.py": "",
    "tests/test_capability011_documentation.py": "",
    "docs/architecture/adr/ADR-017-portable-editorial-project-resume-export.md": "",
    "docs/architecture/baselines/Architecture_Baseline_2026.08.02v13.md": "",
    "docs/demos/Capability-011-Portable-Editorial-Project.md": "",
    "scripts/bootstrap_capability009_article_engine_publication_package.py": "",
    "scripts/bootstrap_capability010_hero_visual_system.py": ""
}

FILES = {
    relative: gzip.decompress(base64.b64decode(payload)).decode("utf-8")
    for relative, payload in _BLOBS.items()
}
PUBLICATION_PACKAGE = FILES["studio/publication_package.py"]


class CapabilityError(RuntimeError):
    """Raised when the Capability 011 bootstrap cannot continue safely."""


def run(command: list[str], root: Path, *, capture: bool = False) -> str:
    result = subprocess.run(
        command, cwd=root, text=True, capture_output=capture, check=False
    )
    if result.returncode:
        detail = (result.stderr or result.stdout or "command failed").strip()
        raise CapabilityError(f"{' '.join(command)}: {detail}")
    return result.stdout if capture else ""


def repository_root() -> Path:
    root = Path(__file__).resolve().parents[1]
    if root.name != EXPECTED_REPOSITORY or not (root / ".git").exists():
        raise CapabilityError("Run from the expected repository.")
    return root


def changed_paths(root: Path) -> set[str]:
    output = run(
        ["git", "status", "--porcelain=v1", "--untracked-files=all"],
        root,
        capture=True,
    )
    paths: set[str] = set()
    for line in output.splitlines():
        value = line[3:]
        if " -> " in value:
            value = value.split(" -> ", 1)[1]
        paths.add(value)
    return paths


def allowed_paths() -> set[str]:
    return {*FILES, SCRIPT_PATH}


def verify_branch(root: Path) -> None:
    branch = run(["git", "branch", "--show-current"], root, capture=True).strip()
    if branch not in EXPECTED_BRANCHES:
        expected = ", ".join(sorted(EXPECTED_BRANCHES))
        raise CapabilityError(f"Expected one of {expected}; found {branch}.")


def verify_worktree(root: Path) -> None:
    unexpected = changed_paths(root) - allowed_paths()
    if unexpected:
        raise CapabilityError(
            "Unexpected working-tree paths: " + ", ".join(sorted(unexpected))
        )


def preview(root: Path) -> None:
    verify_branch(root)
    verify_worktree(root)
    print("Capability 011 Portable Editorial Project preview - no files changed.")
    print("Schema: narrow RC1 runtime-supported fields only.")
    print("Generated or restored paths:")
    for relative in sorted(FILES):
        print(f"- {relative}")
    print("Decisions:")
    print("- deterministic Markdown and optional ZIP")
    print("- strict malformed, unsupported, invalid, stale, and blocked states")
    print("- no fabricated legacy schema or deferred runtime")


def apply(root: Path) -> None:
    before = hashlib.sha256((root / SCRIPT_PATH).read_bytes()).hexdigest()
    for relative, content in FILES.items():
        path = root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.is_file() or path.read_text(encoding="utf-8") != content:
            path.write_text(content, encoding="utf-8")
    after = hashlib.sha256((root / SCRIPT_PATH).read_bytes()).hexdigest()
    if before != after:
        raise CapabilityError("Bootstrap modified itself during apply.")


def validate_generated(root: Path) -> None:
    mismatches = [
        relative for relative, expected in FILES.items()
        if not (root / relative).is_file()
        or (root / relative).read_text(encoding="utf-8") != expected
    ]
    if mismatches:
        raise CapabilityError(
            "Generated content mismatch: " + ", ".join(sorted(mismatches))
        )


def validate_repository(root: Path) -> None:
    run([sys.executable, "-m", "compileall", "-q", "studio", "scripts", "tests"], root)
    run([sys.executable, "-m", "unittest", "discover", "-s", "tests", "-v"], root)
    run([sys.executable, "studio.py", "validate"], root)
    run(["git", "diff", "--check"], root)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    root = repository_root()
    if not args.apply:
        preview(root)
        return 0
    verify_branch(root)
    verify_worktree(root)
    apply(root)
    verify_worktree(root)
    validate_generated(root)
    validate_repository(root)
    print(SENTINEL)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except CapabilityError as exc:
        print(f"Capability 011 bootstrap stopped: {exc}", file=sys.stderr)
        raise SystemExit(1)
